let input;
try {
  input = typeof query === 'string' ? JSON.parse(query) : query;
} catch (e) {
  return JSON.stringify({ error: 'Input konnte nicht geparsed werden. Erwartet wird ein JSON-Objekt mit den Feldern proposal (Array), personenanzahl (number), menuBudget (number) und mindestAnzahlProKategorie (Object). Fehler: ' + e.message });
}
const { proposal, personenanzahl, menuBudget, mindestAnzahlProKategorie } = input;
if (!Array.isArray(proposal) || proposal.length === 0) {
  return JSON.stringify({ error: 'proposal muss ein nicht-leeres Array sein.' });
}
if (typeof personenanzahl !== 'number' || personenanzahl <= 0) {
  return JSON.stringify({ error: 'personenanzahl muss eine positive Zahl sein.' });
}
if (typeof menuBudget !== 'number' || menuBudget <= 0) {
  return JSON.stringify({ error: 'menuBudget muss eine positive Zahl sein.' });
}
// USt: Backend rechnet 10% auf Speisen (20% nur fuer "Getraenk (alkoholisch)" - existiert aktuell nicht im Katalog).
// Die Verwaltungspauschale ist USt-frei und bereits aus menuBudget herausgerechnet.
const VAT_RATE = 0.10;
const dishes = proposal.map(function(d) {
  const pricePerPerson = Number(d.pricePerPerson) || 0;
  const count = Number(d.count) || 0;
  const nettoSubtotal = Math.round(pricePerPerson * count * 100) / 100;
  const ustBetrag = Math.round(nettoSubtotal * VAT_RATE * 100) / 100;
  const subtotal = Math.round((nettoSubtotal + ustBetrag) * 100) / 100;
  return { menuItemId: d.menuItemId, name: d.name, category: d.category, pricePerPerson: Math.round(pricePerPerson * 100) / 100, count: count, nettoSubtotal: nettoSubtotal, ustSatz: VAT_RATE, ustBetrag: ustBetrag, subtotal: subtotal };
});
const gesamtNetto = Math.round(dishes.reduce(function(sum, d) { return sum + d.nettoSubtotal; }, 0) * 100) / 100;
const gesamtUst = Math.round(dishes.reduce(function(sum, d) { return sum + d.ustBetrag; }, 0) * 100) / 100;
const gesamtkosten = Math.round((gesamtNetto + gesamtUst) * 100) / 100; // Brutto inkl. USt, wie Backend
const differenz = Math.round((menuBudget - gesamtkosten) * 100) / 100;
const budgetEingehalten = gesamtkosten <= menuBudget;
const countByCategory = {};
dishes.forEach(function(d) {
  if (!countByCategory[d.category]) countByCategory[d.category] = 0;
  countByCategory[d.category] += d.count;
});
const kategorienCheck = Object.keys(countByCategory).map(function(cat) {
  return { kategorie: cat, count_summe: countByCategory[cat], soll: personenanzahl, passt: countByCategory[cat] === personenanzahl };
});
const kategorienOk = kategorienCheck.every(function(c) { return c.passt; });
const anzahlProKategorie = {};
dishes.forEach(function(d) {
  if (!anzahlProKategorie[d.category]) anzahlProKategorie[d.category] = 0;
  anzahlProKategorie[d.category] += 1;
});
const anzahlCheck = Object.keys(mindestAnzahlProKategorie || {}).map(function(cat) {
  const ist = anzahlProKategorie[cat] || 0;
  const soll = mindestAnzahlProKategorie[cat];
  return { kategorie: cat, anzahl_ist: ist, anzahl_soll: soll, passt: ist >= soll };
});
const anzahlOk = anzahlCheck.every(function(c) { return c.passt; });
const teuersteGerichte = dishes.slice().sort(function(a, b) { return b.subtotal - a.subtotal; }).slice(0, 3).map(function(d) {
  return { name: d.name, category: d.category, pricePerPerson: d.pricePerPerson, count: d.count, subtotal: d.subtotal };
});
let hinweis;
if (!anzahlOk) {
  const fehler = anzahlCheck.filter(function(c) { return !c.passt; }).map(function(c) {
    return 'Kategorie "' + c.kategorie + '": nur ' + c.anzahl_ist + ' verschiedene Gerichte, gefordert sind mindestens ' + c.anzahl_soll;
  }).join('; ');
  hinweis = 'ANZAHL-FEHLER: ' + fehler + '. Pruefe zunaechst mit Menukatalog_filtern (ohne strenge Filter wie max_preis_pro_person oder tags_inkludieren), ob ueberhaupt genuegend verschiedene Gerichte in der Datenbank existieren. Falls JA: ergaenze deine Auswahl um zusaetzliche Gerichte, verteile die counts gleichmaessig neu und rufe Kosten_berechnen erneut auf. Falls NEIN (die Datenbank enthaelt schlicht nicht genug verschiedene Gerichte in dieser Kategorie): nimm so viele wie verfuegbar sind, dokumentiere im reason-Feld der finalen Antwort klar und transparent, dass der Katalog die vom Kunden geforderte Anzahl nicht hergab, und gib dann die finale Antwort.';
} else if (!kategorienOk) {
  const fehler = kategorienCheck.filter(function(c) { return !c.passt; }).map(function(c) {
    return 'Kategorie "' + c.kategorie + '": count-Summe ' + c.count_summe + ', soll ' + c.soll;
  }).join('; ');
  hinweis = 'KONSISTENZ-FEHLER: ' + fehler + '. Pro Kategorie muss die Summe aller count-Werte gleich der Personenanzahl sein. Korrigiere die counts, OHNE die Gericht-Auswahl zu aendern.';
} else if (budgetEingehalten) {
  hinweis = 'Alles passt: Auswahl ist konsistent, vollstaendig und im Budget (Brutto inkl. 10% USt). Du kannst die finale Antwort geben.';
} else {
  const ueberschreitung = Math.abs(differenz);
  const proPersonZuViel = Math.round((ueberschreitung / personenanzahl) * 100) / 100;
  hinweis = 'BUDGET UEBERSCHRITTEN um ' + ueberschreitung.toFixed(2) + ' EUR brutto inkl. USt (= ' + proPersonZuViel.toFixed(2) + ' EUR pro Person zu viel). WICHTIG: Tausche gezielt EIN Gericht (idealerweise das teuerste, das zur Anfrage noch passt) gegen eine guenstigere Alternative aus derselben Kategorie. Verwirf NICHT die gesamte Auswahl. Behalte die kreative Logik deiner Selektion bei. Die teuersten Gerichte sind im Feld "teuerste_gerichte" gelistet.';
}
return JSON.stringify({ gerichte: dishes, gesamtNetto: gesamtNetto, gesamtUst: gesamtUst, gesamtkosten: gesamtkosten, menuBudget: menuBudget, differenz: differenz, budgetEingehalten: budgetEingehalten, kategorien_check: kategorienCheck, kategorien_ok: kategorienOk, anzahl_check: anzahlCheck, anzahl_ok: anzahlOk, teuerste_gerichte: teuersteGerichte, hinweis: hinweis }, null, 2);

const agentData = $input.first().json.output || $input.first().json;
if (!agentData || !agentData.proposal) {
  throw new Error('Agent-Output ungueltig oder kein proposal-Feld: ' + JSON.stringify(agentData).slice(0, 200));
}
const state = $('Parse LLM output to JSON').first().json.state;
const anfrage = state.anfrage;
const kunde = state.kunde;
const pauschale = $('Prepare Budget').first().json.pauschale || 200;
const guestCount = anfrage.personenanzahl;
const budget = anfrage.budget;
let menuGesamtpreis = 0;
let ust = 0;
const VAT_RATE = 0.10; // 10% USt auf Speisen, analog Backend (Pauschale ist USt-frei)
const maxCountByCategory = {};
agentData.proposal.forEach(function(item) {
  const c = item.count || guestCount;
  if (!maxCountByCategory[item.category] || c > maxCountByCategory[item.category]) {
    maxCountByCategory[item.category] = c;
  }
});
const proposal = agentData.proposal.map(function(item) {
  const count = item.count || guestCount;
  const totalPrice = Math.round(item.pricePerPerson * count * 100) / 100;
  menuGesamtpreis += totalPrice;
  ust += Math.round(totalPrice * VAT_RATE * 100) / 100;
  const isAllergikerAlternative = count < maxCountByCategory[item.category];
  return { menuItemId: item.menuItemId, name: item.name, category: item.category, count: count, pricePerPerson: Math.round(item.pricePerPerson * 100) / 100, totalPrice: totalPrice, reason: item.reason || '', isAllergikerAlternative: isAllergikerAlternative };
});
menuGesamtpreis = Math.round(menuGesamtpreis * 100) / 100;
ust = Math.round(ust * 100) / 100;
const totalCosts = Math.round((menuGesamtpreis + ust + pauschale) * 100) / 100; // Brutto inkl. USt
const budgetEingehalten = totalCosts <= budget;
const summary = { proposal: proposal, guestCount: guestCount, menuGesamtpreis: menuGesamtpreis, ust: ust, verwaltungspauschale: pauschale, totalCosts: totalCosts, budget: budget, budgetEingehalten: budgetEingehalten, reason: agentData.reason || '' };
function escapeHtml(str) {
  if (str === null || str === undefined) return '';
  return String(str).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
}
function valueOrFallback(val, fallback) {
  if (val === null || val === undefined || val === '') return fallback || 'nicht angegeben';
