}
const datumDisplay = anfrage.datum_iso ? escapeHtml(anfrage.datum_text) + ' <span style="color:#888;">(konkret: ' + escapeHtml(anfrage.datum_iso) + ')</span>' : escapeHtml(valueOrFallback(anfrage.datum_text));
const uhrzeitDisplay = anfrage.uhrzeit_iso ? escapeHtml(anfrage.uhrzeit_text) + ' <span style="color:#888;">(konkret: ' + escapeHtml(anfrage.uhrzeit_iso) + ')</span>' : escapeHtml(valueOrFallback(anfrage.uhrzeit_text));
