const summaryTable = '<table style="width:100%;border-collapse:collapse;font-size:14px;">' + summaryRows.map(function(row) { return '<tr><td style="padding:6px 12px 6px 0;color:#666;width:160px;vertical-align:top;">' + row[0] + ':</td><td style="padding:6px 0;color:#222;vertical-align:top;">' + row[1] + '</td></tr>'; }).join('') + '</table>';
const dishCards = proposal.map(function(i, idx) {
