  const reasonHtml = i.reason ? '<div style="margin-top:8px;padding-top:8px;border-top:1px solid #eee;color:#555;font-size:13px;font-style:italic;">' + escapeHtml(i.reason) + '</div>' : '';
  return '<div style="border:1px solid #e0e0e0;border-radius:8px;padding:14px 16px;margin-bottom:12px;background:#fafafa;"><div style="font-size:15px;font-weight:bold;color:#222;margin-bottom:8px;">' + (idx + 1) + '. ' + escapeHtml(i.name) + allergikerBadge + '</div><table style="width:100%;border-collapse:collapse;font-size:13px;color:#333;"><tr><td style="padding:2px 0;width:160px;color:#666;">Kategorie:</td><td style="padding:2px 0;">' + escapeHtml(i.category) + '</td></tr><tr><td style="padding:2px 0;color:#666;">Preis pro Person:</td><td style="padding:2px 0;">EUR ' + i.pricePerPerson.toFixed(2) + '</td></tr><tr><td style="padding:2px 0;color:#666;">Anzahl:</td><td style="padding:2px 0;">' + i.count + ' Personen</td></tr><tr><td style="padding:2px 0;color:#666;">Gesamt:</td><td style="padding:2px 0;font-weight:bold;">EUR ' + i.totalPrice.toFixed(2) + '</td></tr></table>' + reasonHtml + '</div>';
}).join('');
const budgetBadge = budgetEingehalten ? '<span style="display:inline-block;background:#d4edda;color:#155724;padding:4px 12px;border-radius:4px;font-weight:bold;">JA</span>' : '<span style="display:inline-block;background:#f8d7da;color:#721c24;padding:4px 12px;border-radius:4px;font-weight:bold;">NEIN - Ueberschreitung!</span>';
const sectionHeader = function(title) { return '<h2 style="background:#2c3e50;color:white;padding:12px 16px;margin:24px 0 16px 0;border-radius:8px;font-size:18px;">' + title + '</h2>'; };
const emailBody = '<div style="font-family:Arial,Helvetica,sans-serif;max-width:680px;margin:0 auto;color:#222;"><h2 style="background:#2c3e50;color:white;padding:12px 16px;margin:0 0 16px 0;border-radius:8px;font-size:18px;">Zusammenfassung der Anfrage</h2>' + summaryTable + sectionHeader('Ausgewaehlte Gerichte') + dishCards + sectionHeader('Kostenuebersicht') + '<table style="width:100%;border-collapse:collapse;font-size:14px;margin-bottom:8px;"><tr><td style="padding:6px 0;color:#666;">Menuepreise gesamt (netto):</td><td style="padding:6px 0;text-align:right;">EUR ' + menuGesamtpreis.toFixed(2) + '</td></tr><tr><td style="padding:6px 0;color:#666;">zzgl. 10% USt:</td><td style="padding:6px 0;text-align:right;">EUR ' + ust.toFixed(2) + '</td></tr><tr><td style="padding:6px 0;color:#666;border-bottom:1px solid #ddd;">Verwaltungspauschale:</td><td style="padding:6px 0;text-align:right;border-bottom:1px solid #ddd;">EUR ' + pauschale.toFixed(2) + '</td></tr><tr><td style="padding:8px 0;font-weight:bold;font-size:16px;">GESAMTPREIS (brutto):</td><td style="padding:8px 0;text-align:right;font-weight:bold;font-size:16px;">EUR ' + totalCosts.toFixed(2) + '</td></tr><tr><td style="padding:6px 0;color:#666;">Budget:</td><td style="padding:6px 0;text-align:right;">EUR ' + Number(budget).toFixed(2) + '</td></tr><tr><td style="padding:10px 0;color:#666;">Budget eingehalten:</td><td style="padding:10px 0;text-align:right;">' + budgetBadge + '</td></tr></table>' + sectionHeader('Begruendung der Auswahl') + '<div style="background:#f8f9fa;border-left:4px solid #2c3e50;padding:14px 16px;font-size:14px;line-height:1.6;color:#333;">' + escapeHtml(summary.reason || '(keine)').replace(/\n/g, '<br>') + '</div></div>';
