const raw = $input.item.json.content?.parts?.[0]?.text ?? "";

function extractJson(s) {
  let t = String(s).trim().replace(/^```(?:json)?/i, "").replace(/```$/, "").trim();
  const start = t.indexOf("{");
  if (start === -1) return null;
  let depth = 0, inStr = false, esc = false;
  for (let i = start; i < t.length; i++) {
    const c = t[i];
    if (inStr) {
      if (esc) { esc = false; }
      else if (c === "\\") { esc = true; }
      else if (c === '"') { inStr = false; }
    } else {
      if (c === '"') inStr = true;
      else if (c === "{") depth++;
      else if (c === "}") { if (--depth === 0) return t.slice(start, i + 1); }
    }
  }
  return null;
}

let parsed = null;
try { parsed = JSON.parse(extractJson(raw)); } catch (e) {}

$input.item.json = {
  state: parsed?.state ?? null,
  antwort_text: parsed?.antwort_text ?? null,
  parse_ok: !!parsed
};
return $input.item;
